<?php
/**
 * MySQL / MariaDB connection settings.
 *
 * The defaults match a fresh XAMPP install (user "root" with no password)
 * and the database created by database/aip_db.sql.
 *
 * For any other server, do NOT edit this file with real credentials:
 * copy config/database.local.example.php to config/database.local.php and
 * put the settings there. That file is ignored by Git, so passwords are
 * never committed.
 */
$dbConfig = [
    'host'     => 'localhost',
    'port'     => 3306,
    'database' => 'aip_db',
    'username' => 'root',
    'password' => '',
];

$localConfig = __DIR__ . '/database.local.php';
if (is_file($localConfig)) {
    $dbConfig = array_merge($dbConfig, require $localConfig);
}

return $dbConfig;
